import base64
import io
import numpy as np
import torch
import torch.nn as nn
import torch.nn.functional as F
import math

# ── CPU only on Kaggle ────────────────────────────────────────────
DEVICE = torch.device("cpu")

# ── ConnectX Environment ──────────────────────────────────────────
class ConnectXEnv:
    def __init__(self, rows=6, cols=7, inarow=4):
        self.rows = rows
        self.cols = cols
        self.inarow = inarow
        self.reset()

    def reset(self):
        self.board = np.zeros((self.rows, self.cols), dtype=np.int8)
        self.current_player = 1
        self.done = False
        self.winner = None
        return self.get_state()

    def get_state(self):
        p1 = (self.board == self.current_player).astype(np.float32)
        p2 = (self.board == (3 - self.current_player)).astype(np.float32)
        return np.stack([p1, p2], axis=0)

    def get_valid_actions(self):
        return [c for c in range(self.cols) if self.board[0, c] == 0]

    def clone(self):
        env = ConnectXEnv(self.rows, self.cols, self.inarow)
        env.board = self.board.copy()
        env.current_player = self.current_player
        env.done = self.done
        env.winner = self.winner
        return env

    def step(self, action):
        row = max(r for r in range(self.rows) if self.board[r, action] == 0)
        self.board[row, action] = self.current_player
        if self._check_win(row, action):
            self.done = True
            self.winner = self.current_player
            reward = 1.0
        elif len(self.get_valid_actions()) == 0:
            self.done = True
            self.winner = None
            reward = 0.0
        else:
            reward = 0.0
        self.current_player = 3 - self.current_player
        return self.get_state(), reward, self.done

    def _check_win(self, row, col):
        b, p, n = self.board, self.board[row, col], self.inarow
        def count_dir(dr, dc):
            cnt, r, c = 0, row + dr, col + dc
            while 0 <= r < self.rows and 0 <= c < self.cols and b[r, c] == p:
                cnt += 1; r += dr; c += dc
            return cnt
        for dr, dc in [(0,1),(1,0),(1,1),(1,-1)]:
            if 1 + count_dir(dr, dc) + count_dir(-dr, -dc) >= n:
                return True
        return False

# ── Bitboard ──────────────────────────────────────────────────────
class Bitboard:
    def __init__(self, rows=6, cols=7, inarow=4):
        self.rows = rows; self.cols = cols; self.inarow = inarow
        self.H = rows + 1; self.SIZE = cols * self.H
        self.reset()

    def reset(self):
        self.bb = [0, 0]
        self.height = [c * self.H for c in range(self.cols)]
        self.move_count = 0

    def clone(self):
        b = Bitboard(self.rows, self.cols, self.inarow)
        b.bb = self.bb[:]; b.height = self.height[:]
        b.move_count = self.move_count
        return b

    def drop(self, col, player):
        bit = 1 << self.height[col]
        self.bb[player] |= bit
        self.height[col] += 1
        self.move_count += 1

    def undo(self, col, player):
        self.height[col] -= 1
        self.bb[player] ^= 1 << self.height[col]
        self.move_count -= 1

    def is_col_full(self, col):
        return self.height[col] >= col * self.H + self.rows

    def valid_cols(self):
        return [c for c in range(self.cols) if not self.is_col_full(c)]

    def is_full(self):
        return self.move_count >= self.rows * self.cols

    def is_win(self, player):
        m, n, H = self.bb[player], self.inarow, self.H
        def check(shift):
            x = m
            for _ in range(n - 1): x &= (x >> shift)
            return bool(x)
        return check(1) or check(H) or check(H+1) or check(H-1)

    @staticmethod
    def from_numpy_board(board_2d, current_player, rows=6, cols=7, inarow=4):
        bb = Bitboard(rows, cols, inarow)
        for c in range(cols):
            for r in range(rows-1, -1, -1):
                p = board_2d[r, c]
                if p != 0:
                    bb.bb[p-1] |= 1 << bb.height[c]
                    bb.height[c] += 1
                    bb.move_count += 1
        return bb

# ── Transposition Table ───────────────────────────────────────────
class TranspositionTable:
    def __init__(self, capacity=1<<17):
        self.mask = capacity - 1
        self._keys     = [None] * capacity
        self._policies = [None] * capacity
        self._values   = [0.0]  * capacity

    def get(self, key):
        slot = key & self.mask
        if self._keys[slot] == key:
            return self._policies[slot], self._values[slot]
        return None, None

    def put(self, key, policy, value):
        slot = key & self.mask
        self._keys[slot] = key; self._policies[slot] = policy; self._values[slot] = value

# ── Simulation Policy ─────────────────────────────────────────────
class SimulationPolicy:
    def __init__(self, rows=6, cols=7, inarow=4, center_weight=2.0):
        self.rows = rows; self.cols = cols; self.inarow = inarow
        mid = (cols - 1) / 2.0
        self.center_scores = np.array(
            [center_weight / (1.0 + abs(c - mid)) for c in range(cols)], dtype=np.float32
        )

    def _immediate_win(self, bb, player_idx):
        for c in bb.valid_cols():
            bb.drop(c, player_idx); win = bb.is_win(player_idx); bb.undo(c, player_idx)
            if win: return c
        return -1

    def select_action(self, bb, current_player_idx):
        valid = bb.valid_cols()
        if not valid: return -1
        w = self._immediate_win(bb, current_player_idx)
        if w != -1: return w
        b = self._immediate_win(bb, 1 - current_player_idx)
        if b != -1: return b
        # FIX: copy weights array — avoids corrupting self.center_scores in-place
        weights = self.center_scores[valid].copy()
        weights = weights / weights.sum()
        return int(np.random.choice(valid, p=weights))

    def rollout(self, bb, starting_player_idx):
        bb = bb.clone(); player = starting_player_idx
        while True:
            valid = bb.valid_cols()
            if not valid: return 0.0
            action = self.select_action(bb, player)
            bb.drop(action, player)
            if bb.is_win(player):   return 1.0 if player == starting_player_idx else -1.0
            if bb.is_full():        return 0.0
            player = 1 - player

    def batch_rollout(self, bb, starting_player_idx, n=4):
        return float(np.mean([self.rollout(bb, starting_player_idx) for _ in range(n)]))

# ── Neural Network ────────────────────────────────────────────────
class ResidualBlock(nn.Module):
    def __init__(self, channels):
        super().__init__()
        self.conv1 = nn.Conv2d(channels, channels, 3, padding=1, bias=False)
        self.bn1   = nn.BatchNorm2d(channels)
        self.conv2 = nn.Conv2d(channels, channels, 3, padding=1, bias=False)
        self.bn2   = nn.BatchNorm2d(channels)

    def forward(self, x):
        r = x; x = F.relu(self.bn1(self.conv1(x)))
        return F.relu(self.bn2(self.conv2(x)) + r)

class AlphaZeroNet(nn.Module):
    def __init__(self, rows=6, cols=7, num_res_blocks=5, channels=64):
        super().__init__()
        self.rows = rows; self.cols = cols
        self.stem = nn.Sequential(
            nn.Conv2d(2, channels, 3, padding=1, bias=False),
            nn.BatchNorm2d(channels), nn.ReLU()
        )
        self.res_blocks = nn.Sequential(*[ResidualBlock(channels) for _ in range(num_res_blocks)])
        self.policy_head = nn.Sequential(
            nn.Conv2d(channels, 2, 1, bias=False), nn.BatchNorm2d(2), nn.ReLU(),
            nn.Flatten(), nn.Linear(2 * rows * cols, cols)
        )
        self.value_head = nn.Sequential(
            nn.Conv2d(channels, 1, 1, bias=False), nn.BatchNorm2d(1), nn.ReLU(),
            nn.Flatten(), nn.Linear(rows * cols, 64), nn.ReLU(), nn.Linear(64, 1), nn.Tanh()
        )

    def forward(self, x):
        x = self.res_blocks(self.stem(x))
        return self.policy_head(x), self.value_head(x)

    @torch.no_grad()
    def predict(self, state_np):
        self.eval()
        t = torch.tensor(state_np, dtype=torch.float32).unsqueeze(0)
        logits, value = self(t)
        return F.softmax(logits, dim=-1).squeeze(0).cpu().numpy(), value.squeeze().item()

# ── MCTS ──────────────────────────────────────────────────────────
class MCTSNode:
    __slots__ = ["state","parent","action","children","N","W","Q","P",
                 "valid_actions","done","value","bb","player_idx"]
    def __init__(self, state, parent=None, action=None, prior=0.0,
                 valid_actions=None, done=False, value=0.0, bb=None, player_idx=0):
        self.state=state; self.parent=parent; self.action=action
        self.children={}; self.N=0; self.W=0.0; self.Q=0.0; self.P=prior
        self.valid_actions=valid_actions; self.done=done; self.value=value
        self.bb=bb; self.player_idx=player_idx
    def is_leaf(self): return len(self.children) == 0
    def ucb_score(self, c_puct, parent_N):
        return self.Q + c_puct * self.P * math.sqrt(parent_N) / (1 + self.N)

class MCTS:
    def __init__(self, network, env_config, c_puct=1.5, n_simulations=100,
                 leaf_eval_mode="blend", n_rollouts=4, tt_capacity=1<<17):
        self.network=network; self.env_config=env_config
        self.c_puct=c_puct; self.n_simulations=n_simulations
        self.leaf_eval_mode=leaf_eval_mode; self.n_rollouts=n_rollouts
        rows,cols,inarow = env_config["rows"],env_config["cols"],env_config["inarow"]
        self.sim_policy = SimulationPolicy(rows, cols, inarow)
        self.tt = TranspositionTable(capacity=tt_capacity)

    def _board_key(self, bb):
        return bb.bb[0] * (2 ** bb.SIZE) + bb.bb[1]

    def _nn_predict(self, state_np, key):
        p, v = self.tt.get(key)
        if p is not None: return p, v
        p, v = self.network.predict(state_np)
        self.tt.put(key, p, v)
        return p, v

    def _leaf_value(self, bb, state_np, key, player_idx):
        rv = self.sim_policy.batch_rollout(bb, player_idx, n=self.n_rollouts)
        if self.leaf_eval_mode == "rollout": return rv
        _, nv = self._nn_predict(state_np, key)
        if self.leaf_eval_mode == "nn": return nv
        return 0.5 * nv + 0.5 * rv   # blend

    def _expand(self, node, env, bb, player_idx):
        state_np = env.get_state()
        key = self._board_key(bb)
        probs, value = self._nn_predict(state_np, key)
        valid = env.get_valid_actions()
        masked = np.zeros_like(probs)
        for a in valid: masked[a] = probs[a]
        s = masked.sum()
        masked = masked / s if s > 0 else np.array(
            [1.0/len(valid) if a in valid else 0.0 for a in range(len(probs))]
        )
        for a in valid:
            ce = env.clone(); _, _, done = ce.step(a)
            cbb = bb.clone(); cbb.drop(a, player_idx)
            node.children[a] = MCTSNode(
                state=ce.get_state(), parent=node, action=a, prior=masked[a],
                valid_actions=ce.get_valid_actions() if not done else [],
                done=done, value=1.0 if (done and ce.winner) else 0.0,
                bb=cbb, player_idx=1 - player_idx
            )
        return value

    def search(self, env_root, add_noise=False):
        bb_root = Bitboard.from_numpy_board(
            env_root.board, env_root.current_player, **self.env_config
        )
        root_player_idx = env_root.current_player - 1
        root = MCTSNode(state=env_root.get_state(),
                        valid_actions=env_root.get_valid_actions(),
                        bb=bb_root, player_idx=root_player_idx)
        if not env_root.done:
            self._expand(root, env_root, bb_root, root_player_idx)

        for _ in range(self.n_simulations):
            node = root; env = env_root.clone(); path = [node]
            while not node.is_leaf() and not node.done:
                best = max(node.children.items(),
                           key=lambda kv: kv[1].ucb_score(self.c_puct, node.N))
                env.step(best[0]); node = best[1]; path.append(node)
            value = (-node.value if node.done else
                     -self._leaf_value(node.bb, node.state,
                                       self._board_key(node.bb), node.player_idx))
            if not node.done:
                self._expand(node, env, node.bb, node.player_idx)
            for n in reversed(path):
                n.N += 1; n.W += value; n.Q = n.W / n.N; value = -value

        policy = np.zeros(env_root.cols)
        for a, child in root.children.items(): policy[a] = child.N
        if policy.sum() > 0: policy /= policy.sum()
        return policy

# ── Load model once at import time ───────────────────────────────
MODEL_B64 = ""

def _load():
    buf = io.BytesIO(base64.b64decode(MODEL_B64))
    ckpt = torch.load(buf, map_location="cpu")
    arch = ckpt["architecture"]
    net = AlphaZeroNet(rows=arch["rows"], cols=arch["cols"],
                       num_res_blocks=arch["num_res_blocks"],
                       channels=arch["channels"])
    net.load_state_dict(ckpt["model_state"])
    net.eval()
    # FIX: create MCTS once — not on every agent call
    mcts = MCTS(net, ckpt["env_config"],
                c_puct=1.5, n_simulations=100,
                leaf_eval_mode="blend", n_rollouts=4)
    return mcts, ckpt["env_config"]

_mcts, _env_config = _load()

# ── Kaggle entry point ────────────────────────────────────────────
def my_agent(observation, configuration):
    rows, cols, inarow = configuration.rows, configuration.columns, configuration.inarow
    board = np.array(observation.board, dtype=np.int8).reshape(rows, cols)
    env = ConnectXEnv(rows, cols, inarow)
    env.board = board
    env.current_player = observation.mark
    policy = _mcts.search(env, add_noise=False)
    valid = env.get_valid_actions()
    for c in range(cols):
        if c not in valid: policy[c] = 0.0
    return int(np.argmax(policy))
